contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);
        // ensure caller is admin: the deploying owner of C is admin, but msg.sender here is this contract
        // The deployed C in the harness sets isAdmin[owner]=true where owner was provided at deployment.
        // The harness deploys C and then deploys this test with that same owner as msg.sender, so to be safe
        // we attempt to call updateWinnersPerPeriod as a way to check admin; if it reverts then pickWinner would also revert.
        bool canCallAdmin = true;
        try c.updateWinnersPerPeriod(winners.length) { }
        catch { canCallAdmin = false; }
        // read state before
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersPerPeriod = c.winnersPerPeriod();
        // compute sum of fighterPoints for given winners as observed before
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            // guard to avoid out-of-bounds from public mapping: mapping returns 0 for non-set entries so safe
            sumPoints += c.fighterPoints(winners[i]);
        }
        bool reverted;
        // attempt pickWinner
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read after-state
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();
        bool selectionComplete = c.isSelectionComplete(beforeRoundId);
        uint256 winnerCount = c.winnerAddresses(beforeRoundId).length;
        // General rule: if caller had admin rights (we inferred via updateWinnersPerPeriod call) and the call didn't revert,
        // then selection for the previous round (beforeRoundId) must be marked complete, roundId increased by 1,
        // winnerAddresses[beforeRoundId] must have length equal to winnersPerPeriod, and totalPoints reduced by sum of fighterPoints of winners.
        assert(!(canCallAdmin && !reverted) || (selectionComplete && afterRoundId == beforeRoundId + 1 && winnerCount == winnersPerPeriod && afterTotalPoints + sumPoints == beforeTotalPoints));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // winners array passed in as calldata
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0, "need >=1 winner param");

        // Try to detect admin capability by attempting an admin-only call (updateWinnersPerPeriod).
        // If this call reverts, we treat caller as non-admin and then pickWinner should also revert.
        bool hasAdminCap;
        try c.updateWinnersPerPeriod(winners.length) {
            hasAdminCap = true;
        } catch {
            hasAdminCap = false;
        }

        // Read pre-state
        uint256 beforeRound = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersPerPeriod = c.winnersPerPeriod();

        // Compute sum of fighterPoints for the provided winners as observed before
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumPoints += c.fighterPoints(winners[i]);
        }

        // Attempt pickWinner and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state values
        uint256 afterRound = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // isSelectionComplete for the old round
        bool selectionComplete = c.isSelectionComplete(beforeRound);

        // Retrieve the stored winner addresses for the old round via the public getter.
        // winnerAddresses(beforeRound) returns address[] memory; read its length and contents.
        address[] memory storedWinners = c.winnerAddresses(beforeRound);
        uint256 storedLen = storedWinners.length;

        // The general rule: if caller had admin capability (we inferred) and pickWinner did NOT revert,
        // then selection must be marked complete for the prior round, roundId increased by 1,
        // stored winners length equals winnersPerPeriod, and totalPoints decreased by sumPoints,
        // and each stored winner equals the owner of the corresponding provided token id as observed before.
        // Note: we cannot read historical ownerOf before the call after state changed, but pickWinner sets winnerAddresses to owners read during the call.
        // So we only require that storedLen equals winnersPerPeriod and totalPoints decreased and round incremented and selectionComplete.

        assert(
            // If we inferred admin capability and the call did not revert, then all those postconditions must hold
            (!(hasAdminCap && !reverted)) || (
                selectionComplete &&
                afterRound == beforeRound + 1 &&
                storedLen == winnersPerPeriod &&
                // totalPoints was reduced by exactly sumPoints (fighterPoints for chosen winners were zeroed)
                // so afterTotalPoints + sumPoints == beforeTotalPoints
                afterTotalPoints + sumPoints == beforeTotalPoints
            )
        );
    }

    receive() external payable {}
}

