contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address adminCaller, uint256[] calldata winners) public payable {
        // precondition: winners length > 0 and matches current winnersPerPeriod
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp && wp > 0);

        // ensure adminCaller is marked admin on c by having the deploying owner set it earlier
        // We cannot change c's admin mapping except via c.adjustAdminAccess which requires owner; the deployment already set an owner and marked it admin. The test runs as this contract, so simulate that adminCaller == address(this) is not possible. Instead we will call pickWinner from this contract and rely on c.adjustAdminAccess having been set to true for this contract at deployment time in the harness. If not, pickWinner will revert and we capture that.

        // read state before
        uint256 roundBefore = c.roundId();
        bool selectionBefore = c.isSelectionComplete(roundBefore);
        uint256 totalPointsBefore = c.totalPoints();
        // store points for each winner before
        uint256[] memory ptsBefore = new uint256[](winners.length);
        address[] memory ownersBefore = new address[](winners.length);
        for (uint256 i = 0; i < winners.length; i++) {
            ptsBefore[i] = c.fighterPoints(winners[i]);
            ownersBefore[i] = c._fighterFarmInstance().ownerOf(winners[i]);
        }

        // attempt call and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read state after
        uint256 roundAfter = c.roundId();
        bool selectionAfter = c.isSelectionComplete(roundBefore);
        uint256 totalPointsAfter = c.totalPoints();
        address[] memory recorded = c.winnerAddresses(roundBefore);

        // Rule: if pickWinner did not revert then
        //  - selectionBefore must have been false (cannot re-select)
        //  - recorded.length == winners.length
        //  - for each winner: recorded[i] equals ownerBefore, fighterPoints[winner] == 0, and totalPoints decreased by ptsBefore sum
        //  - isSelectionComplete[roundBefore] is true and roundId incremented by 1
        uint256 sumPts = 0;
        for (uint256 i = 0; i < winners.length; i++) { sumPts += ptsBefore[i]; }

        assert(
            reverted || (
                selectionBefore == false &&
                roundAfter == roundBefore + (selectionAfter ? 1 : 0) &&
                selectionAfter == true &&
                recorded.length == winners.length &&
                totalPointsAfter + sumPts == totalPointsBefore &&
                // each recorded owner matches previously observed owner and fighterPoints reset
                ({
                    bool ok = true;
                    for (uint256 k = 0; k < winners.length; k++) {
                        if (recorded[k] != ownersBefore[k]) { ok = false; break; }
                        if (c.fighterPoints(winners[k]) != 0) { ok = false; break; }
                    }
                    ok;
                })
            )
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256[] calldata winners) public payable {
        // read immutable needed value
        uint256 wp = c.winnersPerPeriod();
        // require the callers to supply exactly the expected number of winners
        require(winners.length == wp && wp > 0);

        // Observe state before attempting pickWinner
        uint256 roundBefore = c.roundId();
        bool selectionBefore = c.isSelectionComplete(roundBefore);
        uint256 totalPointsBefore = c.totalPoints();

        // capture each winner's owner and points before
        uint256 len = winners.length;
        address[] memory ownersBefore = new address[](len);
        uint256[] memory ptsBefore = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            // Observe ownerOf via FighterFarm through C's public getter: C exposes _fighterFarmInstance() is not public,
            // but contract C has a public getter fighterPoints and winnerAddresses; we can get owner via reading from the FighterFarm external contract by calling ownerOf on the known FighterFarm address.
            // However the problem constraints allow only observing c's public surface. There's no getter for its fighterFarm address, but _fighterFarmInstance was set in constructor and there is no public accessor. So instead, we will read owners after pickWinner from c.winnerAddresses(roundBefore) which should be set if call succeeds. For before-owners we only read points.
            ptsBefore[i] = c.fighterPoints(winners[i]);
        }

        // attempt call and capture whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state for the same round index
        uint256 roundAfter = c.roundId();
        bool selectionAfter = c.isSelectionComplete(roundBefore);
        uint256 totalPointsAfter = c.totalPoints();
        address[] memory recorded;
        // winnerAddresses getter returns address[] memory
        recorded = c.winnerAddresses(roundBefore);

        // compute sum of previous points
        uint256 sumPts = 0;
        for (uint256 i = 0; i < len; i++) { sumPts += ptsBefore[i]; }

        // Build the asserted property: either pickWinner reverted, or all of these hold
        // 1) selectionBefore was false
        // 2) selectionAfter is true
        // 3) roundId incremented by 1
        // 4) recorded length equals winners length
        // 5) totalPoints decreased by sumPts
        // 6) each fighterPoints[winner] == 0
        bool ok = true;
        if (!reverted) {
            if (selectionBefore) ok = false;
            if (!selectionAfter) ok = false;
            if (roundAfter != roundBefore + 1) ok = false;
            if (recorded.length != len) ok = false;
            if (totalPointsAfter + sumPts != totalPointsBefore) ok = false;
            for (uint256 i = 0; i < len; i++) {
                if (c.fighterPoints(winners[i]) != 0) { ok = false; break; }
            }
        }

        assert(reverted || ok);
    }

    receive() external payable {}
}

