    function run(address callerAddr, uint256[] calldata winners) public payable {
        // require at least one element to allow reading winnersPerPeriod via c
        require(winners.length > 0);

        // Read current round and winnersPerPeriod
        uint256 beforeRound = c.roundId();
        uint256 wp = c.winnersPerPeriod();

        // If the provided winners length doesn't match the contract's winnersPerPeriod,
        // calling pickWinner should revert for any caller (unless caller is admin) —
        // but we can't change msg.sender here. Instead we test two general properties:
        // 1) If an admin calls pickWinner successfully, fighterPoints for provided ids become zero
        // 2) If pickWinner reverts (not called by admin), then isSelectionComplete and roundId must remain unchanged.

        // Try to call pickWinner and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

