        uint256 afterRound = c.roundId();
        bool afterSelectionComplete = c.isSelectionComplete(beforeRound);

        // If the call reverted then roundId must not have advanced and selection must not be marked complete
        // If the call succeeded then roundId must have incremented by 1 and for each winner id the fighterPoints must be zero
        if (reverted) {
