            // We only can read fighterPoints mapping by calling the public getter for each id
            for (uint256 i = 0; i < winners.length; i++) {
                uint256 id = winners[i];
                uint256 pts = c.fighterPoints(id);
                assert(pts == 0);
            }

            // also ensure the selection is marked complete for the previous round
            assert(afterSelectionComplete == true);
        }
    }

