        // We cannot change msg.sender in calls, so we cannot call addPoints unless this contract is the rankedBattleAddress.
        // Instead we use C.addPoints only if it will revert otherwise; to observe effect we will first read fighterPoints

        // Read before-values
        uint256 len = tokenIds.length;
        uint256[] memory beforePoints = new uint256[](len);
        uint256 totalBeforeSum = 0;
        for (uint i = 0; i < len; i++) {
            beforePoints[i] = c.fighterPoints(tokenIds[i]);
            totalBeforeSum += beforePoints[i];
        }
        uint256 totalBefore = c.totalPoints();

        // Try to call pickWinner. Only succeeds if this contract is an admin. We capture whether it reverted.
        bool reverted;
        try c.pickWinner(tokenIds) {
