        uint256 totalAfter = c.totalPoints();
        uint256[] memory afterPoints = new uint256[](len);
        uint256 totalAfterSum = 0;
        for (uint i = 0; i < len; i++) {
            afterPoints[i] = c.fighterPoints(tokenIds[i]);
            totalAfterSum += afterPoints[i];
        }

        // General invariant: if pickWinner succeeded (did not revert), then for every provided winner tokenId
        // its fighterPoints must be set to zero and totalPoints must have decreased by the sum of their previous points.
        // If pickWinner reverted, we cannot assert state change, so require reverted implies no change is guaranteed.
        assert(
            reverted
            ? (totalAfter == totalBefore && totalAfterSum == totalBeforeSum)
            : (totalAfter == totalBefore - totalBeforeSum && totalAfterSum == 0)
        );
    }

    receive() external payable {}
}

